        {"구절":"약 5:16", "연결점":"의인의 간구는 역사하는 힘이 큼—중보기도의 실제적 능력", "구분":"신약"},
        {"구절":"고후 1:11", "연결점":"많은 사람의 기도로 은사를 받음—공동체 기도의 실질적 효과", "구분":"신약"}
