        {"상황":"공동체 안에서 고립감을 느끼는 성도", "성경원리":"성령의 코이노니아는 이미 우리를 연결하고 있다. 고립은 느낌이지 사실이 아닐 수 있다 (빌 2:1)", "실제적용":"성령 안에서의 연결을 신학적으로 확인시켜주고, 구체적인 관계 형성 단계를 함께 계획하라"}
